class Money:
    """An amount of money represented as an integer number of cents."""

    def __init__(self, cents):
        self.cents = int(cents)

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return Money(self.cents + other.cents)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self.cents == other.cents

    def __hash__(self):
        return hash(self.cents)

    def __repr__(self):
        return 'Money(%r)' % (self.cents,)

    def __str__(self):
        sign = '-' if self.cents < 0 else ''
        absolute = abs(self.cents)
        dollars, remainder = divmod(absolute, 100)
        return '%s$%s.%02d' % (sign, format(dollars, ','), remainder)

    def split(self, n):
        """Split this amount into n parts, distributing leftover cents fairly."""
        if n <= 0:
            raise ValueError('cannot split into fewer than one part')
        base, remainder = divmod(self.cents, n)
        # divmod with negative values gives a negative remainder; make the
        # leftover non-negative so the first `remainder` parts get one extra cent.
        if remainder < 0:
            base += 1
            remainder += n
        return [Money(base + (1 if i < remainder else 0)) for i in range(n)]
